<?php $settings = site_settings(); ?>
<section class="page-hero"><div class="container"><p class="eyebrow"><span></span><?= e(tr('CONTACT', 'CONTACT')) ?></p><h1><?= e(tr('Nous sommes à votre écoute.', 'We’re here to help.')) ?></h1><p><?= e(tr('Une question sur le programme ou sur une candidature déjà envoyée ?', 'Questions about the programme or an application you have already submitted?')) ?></p></div></section>
<section class="section section-paper"><div class="container contact-layout"><form class="contact-form" method="post"><?= csrf_field() ?><input type="hidden" name="action" value="contact"><h2><?= e(tr('Envoyer un message','Send a message')) ?></h2><label class="field"><?= e(tr('Nom','Name')) ?><input name="name" required></label><label class="field"><?= e(tr('Adresse e-mail','Email address')) ?><input type="email" name="email" required></label><label class="field"><?= e(tr('Votre message','Your message')) ?><textarea name="message" rows="6" minlength="10" required></textarea></label><button class="button button-green" type="submit"><?= e(tr('Envoyer','Send')) ?> <i class="bi bi-send"></i></button></form><aside class="contact-info"><h2><?= e(tr('Coordonnées','Contact details')) ?></h2><?php if(!empty($settings['official_email'])): ?><p><i class="bi bi-envelope"></i><a href="mailto:<?= e($settings['official_email']) ?>"><?= e($settings['official_email']) ?></a></p><?php endif; ?><?php if(!empty($settings['phone'])): ?><p><i class="bi bi-telephone"></i><?= e($settings['phone']) ?></p><?php endif; ?><?php if(!empty($settings['address'])): ?><p><i class="bi bi-geo-alt"></i><?= e($settings['address']) ?></p><?php endif; ?><?php if(!empty($settings['whatsapp'])): $phone=preg_replace('/\D+/','',$settings['whatsapp']); ?><p><i class="bi bi-whatsapp"></i><a href="https://wa.me/<?= e($phone) ?>" target="_blank" rel="noopener noreferrer"><?= e(tr('Écrire sur WhatsApp','Message us on WhatsApp')) ?></a></p><?php endif; ?><?php foreach(['facebook_url'=>'Facebook','instagram_url'=>'Instagram','x_url'=>'X'] as $key=>$label): if(!empty($settings[$key])): ?><p><i class="bi bi-arrow-up-right"></i><a href="<?= e($settings[$key]) ?>" target="_blank" rel="noopener noreferrer"><?= e($label) ?></a></p><?php endif; endforeach; ?></aside></div></section>
